/**
 * Each tenant's MASTER_KEY, generated by the platform and escrowed encrypted
 * with PLATFORM_KEY (decision D4, docs/hosted/DECISIONS.md).
 *
 * The tenant key is the same kind of key a self-hoster makes with
 * `openssl rand -base64 32`, so the customer's OpenPing treats it exactly
 * like a plain install's. Its key id is computed by OpenPing's own
 * `keyIdFor`, so `escrowed_keys.kid` matches the `v2:<kid>:` prefix of every
 * value the tenant encrypts, and a restore can tell which escrowed key it
 * needs.
 *
 * The escrowed form is `v1:<iv>:<ciphertext>` (base64url), AES-256-GCM under
 * PLATFORM_KEY, with additional data binding it to its tenant and key id: a
 * ciphertext copied onto another tenant's row doesn't decrypt.
 */

import { base64urlDecode, base64urlEncode, generatePlatformCallSecret, isPlatformCallSecret } from "../../src/shared/hosted-contract";
import { b64decode, b64encode, isValidMasterKey, keyIdFor } from "../../src/worker/lib/crypto";
import { PermanentError } from "./errors";

const ESCROW_VERSION = "v1";
const AAD_LABEL = "openping/escrowed-master-key/v1";

/** A new tenant MASTER_KEY: 32 random bytes, standard base64 (what OpenPing's MASTER_KEY is). */
export function generateMasterKey(): string {
  return b64encode(crypto.getRandomValues(new Uint8Array(32)));
}

/** PLATFORM_KEY is 32 random bytes in standard base64, like a MASTER_KEY (`openssl rand -base64 32`). */
export function isValidPlatformKey(value: string | undefined): value is string {
  return isValidMasterKey(value);
}

async function importPlatformKey(platformKey: string): Promise<CryptoKey> {
  if (!isValidPlatformKey(platformKey)) throw new PermanentError("PLATFORM_KEY must be 32 bytes, base64-encoded");
  const raw = b64decode(platformKey);
  return crypto.subtle.importKey("raw", new Uint8Array(raw), { name: "AES-GCM" }, false, ["encrypt", "decrypt"]);
}

function additionalData(tenantId: string, kid: string): Uint8Array<ArrayBuffer> {
  return new Uint8Array(new TextEncoder().encode(`${AAD_LABEL}|${tenantId}|${kid}`));
}

export interface EscrowedKey {
  kid: string;
  ciphertext: string;
}

/** Seals a tenant's MASTER_KEY for the `escrowed_keys` table. */
export async function escrowMasterKey(masterKey: string, tenantId: string, platformKey: string): Promise<EscrowedKey> {
  const kid = await keyIdFor(masterKey);
  const key = await importPlatformKey(platformKey);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const sealed = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv, additionalData: additionalData(tenantId, kid) },
    key,
    new TextEncoder().encode(masterKey),
  );
  return { kid, ciphertext: `${ESCROW_VERSION}:${base64urlEncode(iv)}:${base64urlEncode(new Uint8Array(sealed))}` };
}

/** Opens an escrowed key. Throws for a wrong PLATFORM_KEY, a wrong tenant or key id, or tampering. */
export async function openEscrowedKey(escrowed: EscrowedKey, tenantId: string, platformKey: string): Promise<string> {
  const [version, ivPart, ctPart, ...rest] = escrowed.ciphertext.split(":");
  const iv = ivPart ? base64urlDecode(ivPart) : null;
  const ct = ctPart ? base64urlDecode(ctPart) : null;
  if (version !== ESCROW_VERSION || rest.length || !iv || iv.length !== 12 || !ct) {
    throw new PermanentError("escrowed key: unknown format");
  }
  const key = await importPlatformKey(platformKey);
  let plain: ArrayBuffer;
  try {
    plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv, additionalData: additionalData(tenantId, escrowed.kid) }, key, ct);
  } catch {
    throw new PermanentError("escrowed key: does not decrypt with this PLATFORM_KEY for this tenant");
  }
  const masterKey = new TextDecoder().decode(plain);
  // The kid is derived from the key itself, so a row whose kid disagrees was not written by escrowMasterKey.
  if (!isValidMasterKey(masterKey) || (await keyIdFor(masterKey)) !== escrowed.kid) {
    throw new PermanentError("escrowed key: key id mismatch");
  }
  return masterKey;
}

/** The tenant's active (not retired) escrowed key, or null. */
export async function activeEscrowedKey(db: D1Database, tenantId: string): Promise<EscrowedKey | null> {
  return db
    .prepare(
      "SELECT kid, ciphertext FROM escrowed_keys WHERE tenant_id = ? AND retired_at IS NULL ORDER BY created_at DESC LIMIT 1",
    )
    .bind(tenantId)
    .first<EscrowedKey>();
}

/**
 * The tenant's MASTER_KEY: the escrowed one, or a new one escrowed now.
 * Two runs racing here can't end up with different keys: at most one active
 * key per tenant (a partial unique index, migration 0002), the INSERT does
 * nothing on a conflict, and the key answered is always the one re-read
 * from the table, so what is uploaded is what is escrowed.
 */
export async function ensureMasterKey(
  db: D1Database,
  tenantId: string,
  platformKey: string,
  now: number,
): Promise<{ masterKey: string; kid: string; created: boolean }> {
  const existing = await activeEscrowedKey(db, tenantId);
  if (existing) return { masterKey: await openEscrowedKey(existing, tenantId, platformKey), kid: existing.kid, created: false };
  const candidate = await escrowMasterKey(generateMasterKey(), tenantId, platformKey);
  const inserted = await db
    .prepare("INSERT INTO escrowed_keys (tenant_id, kid, ciphertext, created_at) VALUES (?, ?, ?, ?) ON CONFLICT DO NOTHING")
    .bind(tenantId, candidate.kid, candidate.ciphertext, now)
    .run();
  const stored = await activeEscrowedKey(db, tenantId);
  if (!stored) throw new Error("escrowed key: not stored");
  return { masterKey: await openEscrowedKey(stored, tenantId, platformKey), kid: stored.kid, created: (inserted.meta.changes ?? 0) > 0 };
}

// ---------------------------------------------------------------------------
// Starter mode: each tenant's PLATFORM_CALL_SECRET (docs/hosted/CONTRACT.md, section 10)
// ---------------------------------------------------------------------------

const CALL_SECRET_AAD = "openping/platform-call-secret/v1";

function callSecretData(tenantId: string): Uint8Array<ArrayBuffer> {
  return new Uint8Array(new TextEncoder().encode(`${CALL_SECRET_AAD}|${tenantId}`));
}

/** Seals a tenant's call secret for `tenant_call_secrets`: AES-256-GCM under PLATFORM_KEY, bound to the tenant id. */
export async function sealCallSecret(secret: string, tenantId: string, platformKey: string): Promise<string> {
  const key = await importPlatformKey(platformKey);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const sealed = await crypto.subtle.encrypt({ name: "AES-GCM", iv, additionalData: callSecretData(tenantId) }, key, new TextEncoder().encode(secret));
  return `${ESCROW_VERSION}:${base64urlEncode(iv)}:${base64urlEncode(new Uint8Array(sealed))}`;
}

/** Opens a sealed call secret. Throws for a wrong PLATFORM_KEY, another tenant's row, or tampering. */
export async function openCallSecret(ciphertext: string, tenantId: string, platformKey: string): Promise<string> {
  const [version, ivPart, ctPart, ...rest] = ciphertext.split(":");
  const iv = ivPart ? base64urlDecode(ivPart) : null;
  const ct = ctPart ? base64urlDecode(ctPart) : null;
  if (version !== ESCROW_VERSION || rest.length || !iv || iv.length !== 12 || !ct) throw new PermanentError("call secret: unknown format");
  const key = await importPlatformKey(platformKey);
  let plain: ArrayBuffer;
  try {
    plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv, additionalData: callSecretData(tenantId) }, key, ct);
  } catch {
    throw new PermanentError("call secret: does not decrypt with this PLATFORM_KEY for this tenant");
  }
  const secret = new TextDecoder().decode(plain);
  if (!isPlatformCallSecret(secret)) throw new PermanentError("call secret: not a PLATFORM_CALL_SECRET");
  return secret;
}

/**
 * A starter tenant's call secrets, opened: the current one and, during a
 * rotation, the next. Null for a tenant without one, or that no longer runs
 * in starter mode (a moved tenant's secret is never accepted).
 */
export async function starterCallSecrets(db: D1Database, tenantId: string, platformKey: string): Promise<{ current: string; next: string | null } | null> {
  const row = await db
    .prepare(
      `SELECT s.ciphertext, s.next_ciphertext FROM tenant_call_secrets s JOIN tenants t ON t.id = s.tenant_id
       WHERE s.tenant_id = ? AND t.runtime = 'starter'`,
    )
    .bind(tenantId)
    .first<{ ciphertext: string; next_ciphertext: string | null }>();
  if (!row) return null;
  return {
    current: await openCallSecret(row.ciphertext, tenantId, platformKey),
    next: row.next_ciphertext ? await openCallSecret(row.next_ciphertext, tenantId, platformKey) : null,
  };
}

/** The tenant's call secret, opened, or null when it has none (a dispatch tenant). */
export async function tenantCallSecret(db: D1Database, tenantId: string, platformKey: string): Promise<string | null> {
  const row = await db.prepare("SELECT ciphertext FROM tenant_call_secrets WHERE tenant_id = ?").bind(tenantId).first<{ ciphertext: string }>();
  return row ? openCallSecret(row.ciphertext, tenantId, platformKey) : null;
}

/**
 * The tenant's call secret: the stored one, or a new one stored now. Like
 * ensureMasterKey, two runs racing here can't end with different secrets:
 * the INSERT does nothing on a conflict and the answer is re-read.
 */
export async function ensureCallSecret(db: D1Database, tenantId: string, platformKey: string, now: number): Promise<string> {
  const existing = await tenantCallSecret(db, tenantId, platformKey);
  if (existing) return existing;
  const sealed = await sealCallSecret(generatePlatformCallSecret(), tenantId, platformKey);
  await db.prepare("INSERT INTO tenant_call_secrets (tenant_id, ciphertext, created_at) VALUES (?, ?, ?) ON CONFLICT DO NOTHING").bind(tenantId, sealed, now).run();
  const stored = await tenantCallSecret(db, tenantId, platformKey);
  if (!stored) throw new Error("call secret: not stored");
  return stored;
}
